def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for x in me if x == 'D')

    # If opponent has never defected
    if opp_d == 0:
        if my_d == 0:
            if n >= 5:
                return 'D'
            return 'C'
        else:
            for i in range(n - 1):
                if me[i] == 'D' and me[i+1] == 'C':
                    return 'D'
            if me[-1] == 'D':
                return 'C'
            return 'C'

    # Exploit if opponent never retaliates to our defections
    if my_d >= 3:
        retaliations = 0
        for i in range(n - 1):
            if me[i] == 'D' and op[i+1] == 'D':
                retaliations += 1
        if retaliations == 0:
            return 'D'

    last_me = me[-1]
    last_op = op[-1]

    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break

    if last_op == 'D':
        if last_me == 'D':
            if run_d == 1:
                return 'C'
            else:
                if run_d >= 4 and opp_c > 0:
                    if n >= 2 and (me[-1] == 'C' or me[-2] == 'C'):
                        return 'D'
                    else:
                        return 'C'
                return 'D'
        else:
            if n >= 2 and (me[-1] == 'D' or me[-2] == 'D'):
                return 'C'
            else:
                return 'D'
    else:
        if last_me == 'D':
            return 'C'
        else:
            if opp_d * 10 < n and n < 90 and rng.random() < 0.05:
                return 'D'
            return 'C'
